Rules.InvariantScript:
If(

    IsBlank(numOfPeople.Selected) ||
    IsBlank(txtLocation.Text) ||

    (
        RadioFatal.Selected.Value = "Yes" &&
        IsBlank(txtFatalities.Text)
    ) ||

    IsBlank(RadioInjured.Selected.Value) ||

    (
        RadioInjured.Selected.Value = "Yes" &&
        IsBlank(txtInjured.Text)
    ) ||

    IsBlank(RatingUrgency.Value) ||
    IsBlank(txtIdentifiers.Text) ||
    IsBlank(txtIssue.Text),

    Notify(
        "Please complete all required selections",
        NotificationType.Error
    ),

    Reset(numOfPeople);
    Reset(txtLocation);
    Reset(txtFatalities);
    Reset(txtInjured);
    Reset(txtIdentifiers);
    Reset(txtIssue);

    Reset(RadioFatal);
    Reset(RadioInjured);

    Reset(RatingUrgency);

    Navigate('success page_incident report')

)
